UPDATE askxuan_ai.ai_skill SET input_schema='{"fields": [{"key": "calendarType", "label": "你的历法", "type": "select", "required": true, "options": [{"value": "solar", "label": "公历"}, {"value": "lunar", "label": "农历"}], "defaultValue": "solar", "helpText": "按已确认的出生资料填写；不确定时请先核对，系统不会猜测。"}, {"key": "birthDate", "label": "你的出生日期", "type": "date", "required": true, "helpText": "按已确认的出生资料填写；不确定时请先核对，系统不会猜测。"}, {"key": "birthTime", "label": "你的出生时间", "type": "time", "required": true, "helpText": "按已确认的出生资料填写；不确定时请先核对，系统不会猜测。"}, {"key": "gender", "label": "你的性别", "type": "select", "required": true, "options": [{"value": "male", "label": "男"}, {"value": "female", "label": "女"}], "helpText": "按已确认的出生资料填写；不确定时请先核对，系统不会猜测。"}, {"key": "partnerCalendarType", "label": "对方的历法", "type": "select", "required": true, "options": [{"value": "solar", "label": "公历"}, {"value": "lunar", "label": "农历"}], "defaultValue": "solar", "helpText": "按已确认的出生资料填写；不确定时请先核对，系统不会猜测。"}, {"key": "partnerBirthDate", "label": "对方的出生日期", "type": "date", "required": true, "helpText": "按已确认的出生资料填写；不确定时请先核对，系统不会猜测。"}, {"key": "partnerBirthTime", "label": "对方的出生时间", "type": "time", "required": true, "helpText": "按已确认的出生资料填写；不确定时请先核对，系统不会猜测。"}, {"key": "partnerGender", "label": "对方的性别", "type": "select", "required": true, "options": [{"value": "male", "label": "男"}, {"value": "female", "label": "女"}], "helpText": "按已确认的出生资料填写；不确定时请先核对，系统不会猜测。"}]}',prompt_template='依据双方各自的八字工具结果并列解释传统文化关系，必须区分你的资料与对方资料；不编造匹配百分比，不断言关系结局。结合用户描述提出可讨论、可核对的相处建议。',version='2.0.0' WHERE code='marriage';
